// Domain warping: fractal noise fed back into its own coordinates, so the pattern
// swirls like marbled paper. iFloat0 on the [Timeline] sets how strong the warp is.
// Try other strengths with its slider in the [Sliders] tab.
#define warp iFloat0

// A pseudo-random number for each point on a grid.
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

// Smooth noise: random values at the grid corners, blended smoothly in between.
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), u.x),
             mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), u.x), u.y);
}

// Fractal noise: five layers of noise, each smaller, fainter and turned a little.
float fbm(vec2 p) {
  float value = 0.0;
  float amplitude = 0.5;
  for (int i = 0; i < 5; i++) {
    value += amplitude * noise(p);
    p = mat2(1.6, 1.2, -1.2, 1.6) * p;
    amplitude *= 0.5;
  }
  return value;
}

// A smooth colour palette made from cosine waves.
vec3 palette(float t) {
  return 0.5 + 0.5 * cos(6.2832 * (t + vec3(0.0, 0.15, 0.3)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -2 to 2.
  vec2 p = 2.0 * (2.0 * fragCoord - iResolution.xy) / iResolution.y;
  float t = 0.15 * iTime;

  // Warp twice: q is noise of p, then r is noise of p pushed along by q.
  vec2 q = vec2(fbm(p + t), fbm(p + vec2(5.2, 1.3) - t));
  vec2 r = vec2(fbm(p + warp * q + vec2(1.7, 9.2)), fbm(p + warp * q + vec2(8.3, 2.8) + t));
  float f = fbm(p + warp * r);

  vec3 col = palette(0.9 * f + 0.4 * length(q) + 0.5);
  col *= 0.35 + f;
  fragColor = vec4(col, 1.0);
}
